use serde::{Deserialize,Serialize};use std::sync::Mutex;
#[derive(Default)]struct Settings{endpoint:String,model:String}
#[derive(Serialize,Deserialize,Clone)]struct Message{role:String,content:String}
#[tauri::command]fn save_settings(api_key:String,endpoint:String,model:String,state:tauri::State<'_,Mutex<Settings>>)->Result<(),String>{if api_key.trim().is_empty(){return Err("Enter an API key".into())}keyring::Entry::new("NexCode","provider-api-key").map_err(|e|e.to_string())?.set_password(&api_key).map_err(|e|e.to_string())?;let mut s=state.lock().map_err(|e|e.to_string())?;s.endpoint=endpoint.trim_end_matches('/').into();s.model=model;Ok(())}
#[tauri::command]async fn chat(messages:Vec<Message>,state:tauri::State<'_,Mutex<Settings>>)->Result<String,String>{let(endpoint,model)={let s=state.lock().map_err(|e|e.to_string())?;(s.endpoint.clone(),s.model.clone())};if endpoint.is_empty()||model.is_empty(){return Err("Configure provider settings first".into())}let key=keyring::Entry::new("NexCode","provider-api-key").map_err(|e|e.to_string())?.get_password().map_err(|_|"No API key saved".to_string())?;let res=reqwest::Client::new().post(format!("{}/v1/chat/completions",endpoint)).bearer_auth(key).json(&serde_json::json!({"model":model,"messages":messages,"stream":false})).send().await.map_err(|e|e.to_string())?;let status=res.status();let body:serde_json::Value=res.json().await.map_err(|e|e.to_string())?;if !status.is_success(){return Err(body["error"]["message"].as_str().unwrap_or("Provider request failed").into())}body["choices"][0]["message"]["content"].as_str().map(str::to_owned).ok_or_else(||"Unexpected provider response".into())}
fn main(){tauri::Builder::default().manage(Mutex::new(Settings::default())).invoke_handler(tauri::generate_handler![save_settings,chat]).run(tauri::generate_context!()).expect("NexCode failed to start")}